<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue';
import { onBeforeRouteLeave,useRouter } from 'vue-router';
import type { PlaybackHistoryEntry,PlayerStats,PlayerTrack } from '@free-new-desk/contracts';
import { createNativeSurfaceLease } from '../native-surface';
import { onPlaybackStage } from '../playback-events';
const router=useRouter();
const surface=ref<HTMLElement|null>(null);const paused=ref(false);const muted=ref(false);const volume=ref(100);const hwdecEnabled=ref(localStorage.getItem('player.hwdec')!=='off');const playbackError=ref('');const playbackCode=ref('');const volumeTouched=ref(false);const autoNext=ref(true);const lastFailed=ref<PlaybackHistoryEntry|null>(null);const draggedIndex=ref(-1);const speed=ref(1);const pip=ref(false);const fullscreen=ref(false);const subtitlePath=ref('');const subtitleDelay=ref(0);const audioDelay=ref(0);const aspect=ref('no');const status=ref('');const stats=ref<PlayerStats|null>(null);const tracks=ref<PlayerTrack[]>([]);const queue=ref<PlaybackHistoryEntry[]>([]);const diagnostics=ref<Record<string,string|number>>({});const seekValue=ref(0);const seeking=ref(false);const surfaceLease=createNativeSurfaceLease('player-view');let removePlaybackStage:(()=>void)|undefined;let removeBackendStage:(()=>void)|undefined;let bufferingStarted=0;let firstFrameStarted=0;let autoAdvanceLocked=false;let lastProgressPersist=0;let timer:ReturnType<typeof setInterval>|undefined;let surfaceTimer:ReturnType<typeof setInterval>|undefined;let observer:ResizeObserver|undefined;let surfaceRaf=0;let lastSurfaceError='';const audioTracks=computed(()=>tracks.value.filter(track=>track.type==='audio'));const subtitleTracks=computed(()=>tracks.value.filter(track=>track.type==='sub'));const resolution=computed(()=>stats.value?.width&&stats.value?.height?stats.value.width+' × '+stats.value.height:'—');const currentQueueEntry=computed(()=>queue.value[0]??null);const currentEpisodes=computed(()=>currentQueueEntry.value?.episodes??[]);const currentEpisodeIndex=computed(()=>{const current=currentQueueEntry.value;if(!current?.episodeId)return-1;return currentEpisodes.value.findIndex(item=>item.id===current.episodeId&&(!current.flag||item.flag===current.flag));});const canPrevious=computed(()=>currentEpisodeIndex.value>0);const canNext=computed(()=>currentEpisodeIndex.value>=0&&currentEpisodeIndex.value<currentEpisodes.value.length-1);const routeFlags=computed(()=>[...new Set(currentEpisodes.value.map(item=>item.flag))]);const nextRouteFlag=computed(()=>{const flags=routeFlags.value;if(flags.length<2)return'';const current=currentQueueEntry.value?.flag??flags[0]!;const position=flags.indexOf(current);return flags[(position+1)%flags.length]??'';});
function playbackCodeOf(message:string){return /^\[(P\d{4})\]/.exec(message)?.[1]??'';}
function stripPlaybackCode(message:string){return message.replace(/^\[(P\d{4})\]\s*/,'');}
function formatTime(value:number|undefined){const total=Math.max(0,Math.floor(value??0));const h=Math.floor(total/3600),m=Math.floor((total%3600)/60),s=total%60;return(h?h.toString().padStart(2,'0')+':':'')+m.toString().padStart(2,'0')+':'+s.toString().padStart(2,'0');}
function formatRate(value:number|undefined){return value&&value>0?(value/1000).toFixed(value>1000000?0:1)+' kbps':'—';}
function formatBytes(value:number|undefined){if(!value||value<=0)return'—';const units=['B','KB','MB','GB'];let n=value,i=0;while(n>=1024&&i<units.length-1){n/=1024;i++;}return n.toFixed(i?1:0)+' '+units[i];}
async function refresh(){try{const[statsResult,tracksResult]=await Promise.all([window.desktop.playback.query('stats'),window.desktop.playback.query('tracks')]);stats.value=statsResult;tracks.value=tracksResult;if(stats.value.pausedForCache&&!bufferingStarted){bufferingStarted=performance.now();void window.desktop.diagnostics.recordPerformance('bufferingCount',1).catch(()=>false);}else if(!stats.value.pausedForCache&&bufferingStarted){void window.desktop.diagnostics.recordPerformance('bufferingDurationMs',performance.now()-bufferingStarted).catch(()=>false);bufferingStarted=0;}if(firstFrameStarted&&(stats.value.width??0)>0&&(stats.value.height??0)>0){void window.desktop.diagnostics.recordPerformance('firstFrameMs',performance.now()-firstFrameStarted).catch(()=>false);firstFrameStarted=0;}paused.value=stats.value.paused;muted.value=stats.value.muted;if(!volumeTouched.value){const persisted=Number(localStorage.getItem('player.volume'));volume.value=Number.isFinite(persisted)&&localStorage.getItem('player.volume')!==null?Math.min(100,Math.max(0,Math.round(persisted))):Math.min(100,Math.round(stats.value.volume));if(localStorage.getItem('player.volume')!==null&&Math.abs(volume.value-stats.value.volume)>=1)void command({command:'volume',value:volume.value});}else volume.value=Math.min(100,Math.round(stats.value.volume));speed.value=stats.value.speed;if(!seeking.value)seekValue.value=stats.value.position;const current=currentQueueEntry.value;if(current&&stats.value.duration>0){current.position=stats.value.position;current.duration=stats.value.duration;if(Date.now()-lastProgressPersist>=5000){lastProgressPersist=Date.now();void window.desktop.history.updateProgress(current.id,stats.value.position,stats.value.duration).catch(()=>undefined);}}if(autoNext.value&&stats.value.duration>0&&stats.value.position>=stats.value.duration-0.6&&canNext.value&&!autoAdvanceLocked){autoAdvanceLocked=true;void playAdjacent(1).finally(()=>setTimeout(()=>{autoAdvanceLocked=false;},1500));}}catch{/* PlayerHost may be starting or have no active media */}}
async function command(value:Parameters<typeof window.desktop.playback.control>[0]){try{const result=await window.desktop.playback.control(value);if(!result.ok)throw new Error(result.detail??'命令失败');status.value='命令已发送';playbackError.value='';playbackCode.value='';await refresh();}catch(error){playbackError.value=error instanceof Error?error.message:String(error);playbackCode.value=playbackCodeOf(playbackError.value);status.value=playbackError.value;}}
async function syncSurface(visible=true){const element=surface.value;if(!element)return;if(visible&&(pip.value||fullscreen.value))return;const rect=element.getBoundingClientRect();if(rect.width<1||rect.height<1)return;try{const syncStarted=performance.now();const ok=await surfaceLease.sync({x:Math.round(rect.left),y:Math.round(rect.top),width:Math.max(1,Math.round(rect.width)),height:Math.max(1,Math.round(rect.height))},visible);void window.desktop.diagnostics.recordPerformance('surfaceSyncMs',performance.now()-syncStarted).catch(()=>false);if(!ok&&visible)throw new Error('PlayerHost rejected window sync');if(lastSurfaceError){lastSurfaceError='';if(status.value.startsWith('播放器区域同步异常：'))status.value='';}}catch(value){const message=value instanceof Error?value.message:String(value);if(message!==lastSurfaceError){lastSurfaceError=message;status.value='播放器区域同步异常：'+message;}}}
function scheduleSurfaceSync(){if(surfaceRaf)return;surfaceRaf=requestAnimationFrame(()=>{surfaceRaf=0;void syncSurface();});}
async function seekAbsolute(){seeking.value=false;await command({command:'seek',value:seekValue.value,absolute:true});}
async function toggleHwdec(){hwdecEnabled.value=!hwdecEnabled.value;const mode=hwdecEnabled.value?'auto-safe':'no';localStorage.setItem('player.hwdec',hwdecEnabled.value?'on':'off');await window.desktop.settings.set('player.hwdec',mode);await command({command:'hwdec',value:mode});window.dispatchEvent(new CustomEvent('fnd:render-mode',{detail:mode}));}
async function togglePause(){paused.value=!paused.value;await command({command:'pause',value:paused.value});}async function toggleMute(){muted.value=!muted.value;await command({command:'mute',value:muted.value});}async function togglePip(){pip.value=!pip.value;await command({command:'pip',value:pip.value});if(!pip.value){await nextTick();scheduleSurfaceSync();}}async function toggleFullscreen(){fullscreen.value=!fullscreen.value;await command({command:'fullscreen',value:fullscreen.value});if(!fullscreen.value){await nextTick();scheduleSurfaceSync();}}async function screenshot(){try{const result=await window.desktop.playback.screenshot();status.value='截图已保存：'+result.path;}catch(error){status.value=error instanceof Error?error.message:String(error);}}
function replayable(item:PlaybackHistoryEntry){return Boolean(item.flag&&item.episodeId);}
async function resumeQueueItem(item:PlaybackHistoryEntry){if(!item.flag||!item.episodeId){status.value='该记录来自旧版本，缺少重播参数；请从点播详情重新播放一次。';return;}try{await window.desktop.playback.play({sourceId:item.sourceId,videoId:item.videoId,videoName:item.videoName,flag:item.flag,episodeId:item.episodeId,episodeName:item.episodeName,...(item.poster?{poster:item.poster}:{}),...(item.episodes?.length?{episodeListJson:JSON.stringify(item.episodes)}:{})});queue.value=await window.desktop.history.list(8);lastFailed.value=null;playbackError.value='';playbackCode.value='';status.value='已继续播放：'+item.videoName+' · '+item.episodeName;await nextTick();scheduleSurfaceSync();}catch(error){lastFailed.value=item;playbackError.value=error instanceof Error?error.message:String(error);playbackCode.value=playbackCodeOf(playbackError.value);status.value=playbackError.value;}}
async function retryPlayback(){if(lastFailed.value)await resumeQueueItem(lastFailed.value);else await command({command:'pause',value:false});}
async function switchRoute(){const flag=nextRouteFlag.value,base=lastFailed.value??currentQueueEntry.value;if(!flag||!base)return;const episode=currentEpisodes.value.find(item=>item.flag===flag&&item.id===base.episodeId)??currentEpisodes.value.find(item=>item.flag===flag)??currentEpisodes.value[0];if(!episode){status.value='该播放项没有其他可用线路。';return;}status.value=`切换到线路「${flag}」…`;await resumeQueueItem({...base,flag:episode.flag,episodeId:episode.id,episodeName:episode.name});}
function openDiagnostics(){void router.push('/settings?section=diagnostics');}
async function playAdjacent(offset:number){const base=currentQueueEntry.value,index=currentEpisodeIndex.value;if(!base||index<0)return;const episode=currentEpisodes.value[index+offset];if(!episode)return;await resumeQueueItem({...base,flag:episode.flag,episodeId:episode.id,episodeName:episode.name});}
async function saveQueue(){await window.desktop.settings.set('player.savedQueue',JSON.stringify(queue.value));status.value='播放队列已保存到本机设置。';}
function clearQueue(){if(!window.confirm('确认清空当前播放队列？播放历史不会被删除。'))return;queue.value=[];status.value='当前播放队列已清空（不会删除播放历史）。';}
function dropQueue(target:number){const source=draggedIndex.value;if(source<0||source===target)return;const next=[...queue.value];const moved=next.splice(source,1)[0];if(moved)next.splice(target,0,moved);queue.value=next;draggedIndex.value=-1;void saveQueue();}
async function persistVolume(){volumeTouched.value=true;localStorage.setItem('player.volume',String(volume.value));await command({command:'volume',value:volume.value});}
function keydown(event:KeyboardEvent){const target=event.target as HTMLElement|null;if(target&&['INPUT','SELECT','TEXTAREA'].includes(target.tagName))return;if(event.code==='Space'){event.preventDefault();void togglePause();}else if(event.key==='ArrowLeft')void command({command:'seek',value:-10});else if(event.key==='ArrowRight')void command({command:'seek',value:10});else if(event.key==='ArrowUp'){volume.value=Math.min(100,volume.value+5);void persistVolume();}else if(event.key==='ArrowDown'){volume.value=Math.max(0,volume.value-5);void persistVolume();}else if(event.key.toLowerCase()==='f')void toggleFullscreen();else if(event.key.toLowerCase()==='m')void toggleMute();else if(event.key.toLowerCase()==='p')void togglePip();}
onMounted(async()=>{window.addEventListener('keydown',keydown);removePlaybackStage=onPlaybackStage(detail=>{status.value=detail.message;if(detail.stage==='source-resolving'||detail.stage==='connecting')firstFrameStarted=performance.now();if(detail.stage==='failed'){playbackError.value=detail.error??detail.message;playbackCode.value=playbackCodeOf(playbackError.value);}else if(detail.stage==='playing'){playbackError.value='';playbackCode.value='';}});removeBackendStage=window.desktop.playback.onStageChanged(detail=>{status.value=detail.message;if(detail.stage==='source-resolving'||detail.stage==='connecting')firstFrameStarted=performance.now();if(detail.stage==='failed'){playbackError.value=detail.error??detail.message;playbackCode.value=playbackCodeOf(playbackError.value);}else if(detail.stage==='playing'){playbackError.value='';playbackCode.value='';}});window.addEventListener('resize',scheduleSurfaceSync);window.addEventListener('scroll',scheduleSurfaceSync,true);const [recent,diag,savedSettings]=await Promise.all([window.desktop.history.list(8).catch(()=>[]),window.desktop.diagnostics.get().catch(()=>({})),window.desktop.settings.list().catch(()=>({} as Record<string,string>))]);autoNext.value=savedSettings['player.autoNext']!=='false';let saved:PlaybackHistoryEntry[]=[];try{const parsed=JSON.parse(savedSettings['player.savedQueue']??'[]') as unknown;if(Array.isArray(parsed))saved=parsed as PlaybackHistoryEntry[];}catch{/* ignore malformed saved queue */}queue.value=recent.length?recent:saved;diagnostics.value=diag;await nextTick();observer=new ResizeObserver(()=>scheduleSurfaceSync());if(surface.value)observer.observe(surface.value);void refresh();scheduleSurfaceSync();timer=setInterval(()=>{void refresh();},1000);surfaceTimer=setInterval(()=>scheduleSurfaceSync(),1000);});onBeforeRouteLeave(async()=>{const started=performance.now();await surfaceLease.release();const elapsed=performance.now()-started;void window.desktop.diagnostics.recordPerformance('surfaceHideMs',elapsed).catch(()=>false);if(window.desktop.app.isUiSmoke()&&elapsed>200)throw new Error(`Player native surface hide exceeded 200ms: ${elapsed.toFixed(1)}ms`);});
onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);window.removeEventListener('resize',scheduleSurfaceSync);window.removeEventListener('scroll',scheduleSurfaceSync,true);removePlaybackStage?.();removeBackendStage?.();observer?.disconnect();if(timer)clearInterval(timer);if(surfaceTimer)clearInterval(surfaceTimer);if(surfaceRaf)cancelAnimationFrame(surfaceRaf);void surfaceLease.release();});
</script>

<template>
  <section class="page player-page">
    <div class="page-heading split"><div><span class="back-label">播放器</span><h1>原生播放控制台</h1><p>PlayerHost C++ x64 · libmpv · D3D11 硬件加速</p></div><div class="toolbar-group"><button class="secondary-button" @click="screenshot">截图</button><button class="secondary-button" @click="togglePip">{{pip?'退出 PiP':'画中画'}}</button><button class="secondary-button" @click="toggleFullscreen">{{fullscreen?'退出全屏':'全屏'}}</button><button class="secondary-button" :class="{active:hwdecEnabled}" @click="toggleHwdec">{{hwdecEnabled?'硬件解码':'软件解码'}}</button></div></div>
    <div class="player-workspace">
      <div class="player-stage-column">
        <div ref="surface" class="player-surface concept-surface" role="region" aria-label="视频播放区域"><div class="surface-placeholder"><span class="surface-seal">山河无恙<br/>人间皆安</span><strong>Native libmpv Video Surface</strong><small>开始播放后，原生视频窗口严格嵌入此区域。</small></div></div>
        <div class="progress-panel panel"><div class="progress-times"><span>{{formatTime(seekValue)}}</span><span>{{formatTime(stats?.duration)}}</span></div><input v-model.number="seekValue" class="player-progress" type="range" min="0" :max="Math.max(1,stats?.duration??1)" step="0.1" @pointerdown="seeking=true" @pointerup="seekAbsolute" @change="seekAbsolute"/></div>
        <div class="transport-bar panel"><button class="icon-control episode-control" :disabled="!canPrevious" @click="playAdjacent(-1)">上一集</button><button class="icon-control" @click="command({command:'seek',value:-10})">−10</button><button class="icon-control primary" @click="togglePause">{{paused?'▶':'Ⅱ'}}</button><button class="icon-control" @click="command({command:'seek',value:10})">+10</button><button class="icon-control episode-control" :disabled="!canNext" @click="playAdjacent(1)">下一集</button><button class="icon-control" @click="toggleMute">{{muted?'静音':'声音'}}</button><input v-model.number="volume" class="volume-slider" type="range" min="0" max="100" aria-label="音量" @change="persistVolume"/><select v-model.number="speed" @change="command({command:'speed',value:speed})"><option v-for="value in [0.5,1,1.25,1.5,2,3]" :key="value" :value="value">{{value}}×</option></select><span class="transport-spacer"/><button class="secondary-button" @click="command({command:'stop'})">停止</button></div>
      </div>

      <aside class="panel playback-info"><div class="panel-heading"><div><span class="panel-kicker">播放信息</span><h2>媒体与运行状态</h2></div></div><dl class="info-list"><div><dt>播放位置</dt><dd>{{formatTime(stats?.position)}} / {{formatTime(stats?.duration)}}</dd></div><div><dt>容器 / 视频</dt><dd>{{stats?.containerFormat||'—'}} / {{stats?.videoFormat||'—'}}</dd></div><div><dt>分辨率 / 帧率</dt><dd>{{resolution}} / {{stats?.fps?stats.fps.toFixed(2)+' fps':'—'}}</dd></div><div><dt>视频码率</dt><dd>{{formatRate(stats?.videoBitrate)}}</dd></div><div><dt>音频</dt><dd>{{stats?.audioFormat||'—'}} · {{stats?.audioChannels||'—'}} ch · {{stats?.sampleRate?Math.round(stats.sampleRate/1000)+' kHz':'—'}}</dd></div><div><dt>音频码率</dt><dd>{{formatRate(stats?.audioBitrate)}}</dd></div><div><dt>硬件解码</dt><dd>{{stats?.hwdec||'—'}}</dd></div><div><dt>缓存</dt><dd>{{stats?formatBytes(stats.cacheBytes)+' / '+formatBytes(stats.cacheMaxBytes)+' · '+stats.cacheDuration.toFixed(1)+' 秒':'—'}}</dd></div><div><dt>来源 / 片源</dt><dd>{{currentQueueEntry?.sourceName??'—'}} / {{currentQueueEntry?.episodeName??'—'}}</dd></div><div><dt>文件大小</dt><dd>{{formatBytes(stats?.fileSize)}}</dd></div><div class="path-row"><dt>媒体路径</dt><dd :title="stats?.path??''">{{stats?.path||'—'}}</dd></div></dl><div class="runtime-box"><strong>PlayerHost 运行信息</strong><small>应用 V{{diagnostics.appVersion??'—'}} · {{diagnostics.architecture??'x64'}}</small><small>libmpv：{{String(diagnostics.libmpv??'—').split(';')[0]}}</small><small>GPU：{{String(diagnostics.gpu??'—').slice(0,64)}}</small><small>编译运行时：MSVC 2022 (x64)</small><small>平台：Windows {{diagnostics.windowsBuild??'—'}} · {{diagnostics.architecture??'x64'}}</small></div><div class="advanced-player-controls"><label>画面比例<select v-model="aspect" @change="command({command:'aspect-ratio',value:aspect})"><option value="no">自动</option><option value="16:9">16:9</option><option value="4:3">4:3</option><option value="2.35:1">2.35:1</option></select></label><label>音轨<select @change="command({command:'audio-track',value:($event.target as HTMLSelectElement).value})"><option value="auto">自动</option><option v-for="track in audioTracks" :key="track.id" :value="track.id">{{track.title||track.language||track.id}}</option></select></label><label>字幕轨<select @change="command({command:'subtitle-track',value:($event.target as HTMLSelectElement).value})"><option value="auto">自动</option><option value="no">关闭</option><option v-for="track in subtitleTracks" :key="track.id" :value="track.id">{{track.title||track.language||track.id}}</option></select></label><label>字幕延迟<input v-model.number="subtitleDelay" type="number" step="0.1" @change="command({command:'subtitle-delay',value:subtitleDelay})"/></label><label>音频延迟<input v-model.number="audioDelay" type="number" step="0.1" @change="command({command:'audio-delay',value:audioDelay})"/></label><label>外挂字幕<div class="inline-input"><input v-model="subtitlePath" placeholder="C:\\Subtitles\\movie.ass"/><button :disabled="!subtitlePath" @click="command({command:'subtitle-add',value:subtitlePath})">加载</button></div></label></div></aside>
    </div>
    <div v-if="playbackError" class="player-error" role="alert"><div class="player-error-head"><strong>播放失败</strong><span v-if="playbackCode" class="error-code">错误码 {{playbackCode}}</span></div><p>{{stripPlaybackCode(playbackError)}}</p><p class="error-context">来源：{{currentQueueEntry?.sourceName??'—'}} · 线路：{{currentQueueEntry?.flag||'—'}} · 剧集：{{currentQueueEntry?.episodeName??'—'}}</p><div class="row-actions"><button class="primary-button" @click="retryPlayback">重试</button><button class="secondary-button" :disabled="!nextRouteFlag" :title="nextRouteFlag?`切换到线路「${nextRouteFlag}」`:''" @click="switchRoute">切换线路</button><button class="text-link" @click="openDiagnostics">打开诊断</button></div></div><p v-if="status&&!playbackError" class="status-line">{{status}}</p>
    <section class="panel queue-panel"><div class="panel-heading"><div><span class="panel-kicker">播放队列</span><h2>最近观看</h2></div><div class="queue-actions"><button class="text-link" :disabled="!queue.length" @click="saveQueue">保存队列</button><button class="text-link" :disabled="!queue.length" @click="clearQueue">清空</button><RouterLink class="text-link" to="/history">查看全部</RouterLink></div></div><div v-if="queue.length" class="queue-strip"><button v-for="(item,index) in queue" :key="item.id" class="queue-card" draggable="true" @dragstart="draggedIndex=index" @dragover.prevent @drop="dropQueue(index)" :class="{legacy:!replayable(item)}" :title="replayable(item)?'点击继续播放':'旧记录缺少重播参数'" @click="resumeQueueItem(item)"><div class="queue-thumb"><img v-if="item.poster" :src="item.poster" :alt="item.videoName+' 海报'"/><span v-else>▶</span></div><div><strong>{{item.videoName}}</strong><small>{{item.episodeName}} · {{item.sourceName}} · {{formatTime(item.position)}} / {{formatTime(item.duration)}}</small><progress class="queue-progress" :value="item.position??0" :max="Math.max(1,item.duration??1)" :aria-label="`${item.videoName} 播放进度`"/></div></button></div><div v-else class="compact-empty">当前队列为空，可从最近播放重新建立队列。</div></section>
  </section>
</template>

<style scoped>
.concept-surface{position:relative;overflow:hidden;isolation:isolate}.progress-panel{padding:8px 12px 10px;margin-top:10px}.progress-times{display:flex;justify-content:space-between;font-variant-numeric:tabular-nums;font-size:11px;color:var(--muted)}.player-progress{width:100%;margin:6px 0 0}.runtime-box{display:flex;flex-direction:column;gap:4px;padding:10px 0;margin-top:8px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.runtime-box small{color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.path-row dd{max-width:190px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.queue-card{text-decoration:none;color:inherit;text-align:left;border:0;cursor:pointer}.queue-card.legacy{opacity:.62}.queue-thumb{overflow:hidden}.queue-thumb img{width:100%;height:100%;object-fit:cover}.queue-progress{width:100%;height:4px;margin-top:4px}.queue-actions{display:flex;align-items:center;gap:10px}.episode-control{min-width:58px}.episode-control:disabled{opacity:.35;cursor:not-allowed}
</style>
<style scoped>
.player-error{display:grid;gap:6px;margin:12px 0;padding:12px 14px;border:1px solid #d45858;border-radius:10px;background:rgba(180,45,45,.12);color:#a92f2f}.player-error-head{display:flex;align-items:center;gap:10px}.player-error .error-code{font-size:11px;padding:2px 7px;border-radius:999px;border:1px solid currentColor}.player-error .error-context{color:var(--muted);font-size:11px}.player-error .row-actions{display:flex;gap:9px;align-items:center}.queue-card[draggable=true]{cursor:grab}.queue-card[draggable=true]:active{cursor:grabbing}
</style>